import { useEffect, useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson, putJson, RefusedError } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { useUser } from '../session/useUser';
import { claimsKey } from './claimsQuery';
import type { Claim } from './claimsQuery';

const AMOUNT = /^\d+(\.\d{1,2})?$/;
const DATE = /^\d{4}-\d{2}-\d{2}$/;

type Body = { amount: string; date: string; note: string };

/** The one form a person's claims are added and edited through. Opening a claim's editor fills it. */
export function ClaimForm({ sheetId, personId, editing, onDone }: {
  sheetId: string;
  personId: number;
  editing: Claim | undefined;
  onDone: () => void;
}) {
  const queryClient = useQueryClient();
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState('');
  const [note, setNote] = useState('');
  const [error, setError] = useState('');

  // Opening an editor (or closing it) refills the form. A blank date is the sheet's today.
  useEffect(() => {
    setAmount(editing?.amount ?? '');
    setDate(editing?.date ?? '');
    setNote(editing?.note ?? '');
    setError('');
  }, [editing?.id]); // eslint-disable-line react-hooks/exhaustive-deps

  const [user] = useUser();
  const once = useSubmitOnce();
  const save = useMutation({
    mutationFn: (body: Body) =>
      editing
        ? putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${editing.id}`, body, user)
        : postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/claims`, body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
      if (editing) {
        onDone();
      } else {
        setAmount('');
        setDate('');
        setNote('');
      }
    },
    onError: (e) => setError(e instanceof RefusedError ? e.message : 'The claim could not be saved.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const a = amount.trim();
    const d = date.trim();
    if (!AMOUNT.test(a)) {
      setError('The amount must be a number of 0.00 or more, with up to two decimals.');
      return;
    }
    if (d !== '' && !DATE.test(d)) {
      setError('The date must be yyyy-mm-dd.');
      return;
    }
    once(() => save.mutateAsync({ amount: a, date: d, note: note.trim() }));
  };

  const edit = <T,>(set: (v: T) => void) => (v: T) => {
    set(v);
    setError('');
  };

  return (
    <form data-testid="claim-form" onSubmit={submit}>
      <input
        data-testid="claim-form-amount"
        placeholder="Amount"
        value={amount}
        onChange={(e) => edit(setAmount)(e.target.value)}
      />{' '}
      <input
        data-testid="claim-form-date"
        placeholder="yyyy-mm-dd"
        value={date}
        onChange={(e) => edit(setDate)(e.target.value)}
      />{' '}
      <input
        data-testid="claim-form-note"
        placeholder="Note"
        value={note}
        onChange={(e) => edit(setNote)(e.target.value)}
      />{' '}
      <button type="submit" data-testid="claim-form-submit" disabled={save.isPending}>
        {editing ? 'Save claim' : 'Add claim'}
      </button>
      {error && <p data-testid="claim-form-error">{error}</p>}
    </form>
  );
}
import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { ClaimCells } from '../../slots/defs/claimColumns';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { claimsQuery } from './claimsQuery';
import { ClaimForm } from './ClaimForm';

/** A person's claims, newest first, with the form they are added and edited through. */
function PersonClaims({ sheetId, personId }: { sheetId: string; personId: number }) {
  const claims = (useQuery(claimsQuery(sheetId)).data ?? []).filter((c) => c.personId === personId);
  const [editingId, setEditingId] = useState<number | undefined>();
  const editing = claims.find((c) => c.id === editingId);

  return (
    <td data-testid="person-claims">
      <table>
        <tbody>
          {claims.map((c) => (
            <tr key={c.id} data-testid={`claim-row-${c.id}`}>
              <td data-testid="claim-number">{c.number ?? ''}</td>
              <td data-testid="claim-amount">{c.amount}</td>
              <td data-testid="claim-date">{c.date}</td>
              <td data-testid="claim-note">{c.note}</td>
              <ClaimCells.Slot sheetId={sheetId} claim={c} />
              <td>
                {c.id === editing?.id ? (
                  <button type="button" data-testid="claim-cancel" onClick={() => setEditingId(undefined)}>
                    Cancel
                  </button>
                ) : (
                  <button type="button" data-testid="claim-edit" onClick={() => setEditingId(c.id)}>
                    Edit
                  </button>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <ClaimForm sheetId={sheetId} personId={personId} editing={editing} onDone={() => setEditingId(undefined)} />
    </td>
  );
}

export const contributions = [
  PersonHeaders.fill({ order: 20, Component: () => <th>Claims</th> }),
  PersonCells.fill({ order: 20, Component: PersonClaims }),
];
import { getJson } from '../../api/http';
import type { Person } from '../people/peopleQuery';
import { sheetKey } from '../sheet/sheetQuery';

export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

/**
 * `amount` has two decimals ("12.50"); `date` is yyyy-mm-dd; `number` is given on opening and kept when voided (null for a draft);
 * `settledDue` is the due fixed on settling (null when not settled, or settled while no rate applied on the claim's date);
 * `openedBy` is the user who opened it (null when never opened), who cannot settle it;
 * `stated` is whether its person's last statement bound it, at `statedDue` (null when it had no figure then).
 */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: number | null;
  settledDue: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
};

/**
 * Only OPEN and SETTLED claims count toward claimed, due and every total; drafts and voided ones do not,
 * nor do the OPEN claims of a person on hold.
 */
export const counts = (c: Claim, people: Person[]) =>
  c.status === 'SETTLED' || (c.status === 'OPEN' && !people.find((p) => p.id === c.personId)?.held);

/** Under the sheet's key, so re-loading the sheet re-reads its claims. */
export const claimsKey = (sheetId: string) => [...sheetKey(sheetId), 'claims'] as const;

/** Every claim on the sheet, newest first. */
export const claimsQuery = (sheetId: string) => ({
  queryKey: claimsKey(sheetId),
  queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`),
});

/** Amounts are added up in whole cents, so the sum shows exactly with two decimals. */
export function sumAmounts(claims: Claim[]): string {
  const cents = claims.reduce((total, c) => total + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}
import { useQuery } from '@tanstack/react-query';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { peopleQuery } from '../people/peopleQuery';
import { claimsQuery, counts, sumAmounts } from './claimsQuery';

function useCounting(sheetId: string) {
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  return (useQuery(claimsQuery(sheetId)).data ?? []).filter((c) => counts(c, people));
}

function PersonClaimed({ sheetId, personId }: { sheetId: string; personId: number }) {
  const claims = useCounting(sheetId);
  return <td data-testid="person-claimed">{sumAmounts(claims.filter((c) => c.personId === personId))}</td>;
}

function ClaimedTotal({ sheetId }: { sheetId: string }) {
  const claims = useCounting(sheetId);
  return (
    <p data-testid="rollup">
      Claimed total <strong data-testid="rollup-claimed-total">{sumAmounts(claims)}</strong>
    </p>
  );
}

export const contributions = [
  PersonHeaders.fill({ order: 10, Component: () => <th>Claimed</th> }),
  PersonCells.fill({ order: 10, Component: PersonClaimed }),
  SheetPanel.fill({ order: 20, Component: ClaimedTotal }),
];
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson, RefusedError } from '../../api/http';
import { ClaimCells } from '../../slots/defs/claimColumns';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { useUser } from '../session/useUser';
import { claimsKey } from './claimsQuery';
import type { Claim, ClaimStatus } from './claimsQuery';

const ACTIONS: Array<{ action: string; to: ClaimStatus; label: string }> = [
  { action: 'open', to: 'OPEN', label: 'Open' },
  { action: 'settle', to: 'SETTLED', label: 'Settle' },
  { action: 'void', to: 'VOID', label: 'Void' },
];

/**
 * A claim's status and the buttons that change it. Every button is offered; the server refuses a
 * change the status does not allow, a settle by the user who opened the claim, a clerk's settle of a claim
 * whose due is above the sheet's clerk limit, or any change to a claim dated in a closed period, and the refusal
 * shows on the claim until its next action.
 */
function ClaimStatusCell({ sheetId, claim }: { sheetId: string; claim: Claim }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const [error, setError] = useState('');
  const once = useSubmitOnce();
  const change = useMutation({
    mutationFn: (to: ClaimStatus) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/status/${to}`, {}, user),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
    onError: (e, to) =>
      setError(
        e instanceof RefusedError
          ? e.message
          : to === 'SETTLED' && claim.status === 'OPEN' && claim.openedBy === user
            ? 'The user who opened a claim cannot settle it.'
            : `A ${claim.status} claim cannot become ${to}.`,
      ),
  });

  return (
    <td>
      <span data-testid="claim-status">{claim.status}</span>{' '}
      {ACTIONS.map(({ action, to, label }) => (
        <button
          key={action}
          type="button"
          data-testid={`claim-${action}`}
          disabled={change.isPending}
          onClick={() => {
            setError('');
            once(() => change.mutateAsync(to));
          }}
        >
          {label}
        </button>
      ))}
      {error && <span data-testid="claim-error">{error}</span>}
    </td>
  );
}

export const contribution = ClaimCells.fill({ order: 20, Component: ClaimStatusCell });
import { ClaimCells } from '../../slots/defs/claimColumns';
import type { Claim } from './claimsQuery';

/** Who opened the claim (blank until it is opened). */
function ClaimOpenedBy({ claim }: { sheetId: string; claim: Claim }) {
  return <td data-testid="claim-opened-by">{claim.openedBy ?? ''}</td>;
}

export const contribution = ClaimCells.fill({ order: 25, Component: ClaimOpenedBy });

