import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheetQuery';
import type { Claim } from '../claims/claimsQuery';
import { gradeOn } from '../people/peopleQuery';
import type { Grade, Person } from '../people/peopleQuery';

/**
 * `rate` is a percent with two decimals ("12.50"), in force from `from` (yyyy-mm-dd; null: from the
 * beginning of time). A grade may have several, one per from-date; a grade with no rate has no entry.
 */
export type Rate = { grade: Grade; rate: string; from: string | null };

/** Under the sheet's key, so re-loading the sheet re-reads its rates. */
export const ratesKey = (sheetId: string) => [...sheetKey(sheetId), 'rates'] as const;

export const ratesQuery = (sheetId: string) => ({
  queryKey: ratesKey(sheetId),
  queryFn: () => getJson<Rate[]>(`/api/sheets/${encodeURIComponent(sheetId)}/rates`),
});

/** The grade's rate on the date (yyyy-mm-dd): the one with the latest from-date on or before it, or undefined when none applies. */
export function rateFor(rates: Rate[], grade: Grade | undefined, date: string): string | undefined {
  // No from-date sorts as '', before every date.
  const applying = rates.filter((r) => r.grade === grade && (r.from ?? '') <= date);
  return applying.reduce<Rate | undefined>((best, r) => (!best || (r.from ?? '') > (best.from ?? '') ? r : best), undefined)?.rate;
}

/** A two-decimal string ("12.50") in whole hundredths, exactly. */
function hundredths(value: string): bigint {
  const [whole, frac = ''] = value.trim().split('.');
  return BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
}

function show(cents: bigint): string {
  return `${cents / 100n}.${(cents % 100n).toString().padStart(2, '0')}`;
}

/** Cents of `amount` times `rate` percent, rounded half to even (both are 0 or more). */
export function dueCents(amount: string, rate: string): bigint {
  const product = hundredths(amount) * hundredths(rate);
  const cents = product / 10000n;
  const rest = product % 10000n;
  return rest > 5000n || (rest === 5000n && cents % 2n === 1n) ? cents + 1n : cents;
}

/** `amount` times `rate` percent with two decimals, or n/a when there is no rate. */
export function due(amount: string, rate: string | undefined): string {
  return rate === undefined ? 'n/a' : show(dueCents(amount, rate));
}

/** Due figures added up, skipping n/a. */
export function sumDue(dues: string[]): string {
  return show(dues.filter((d) => d !== 'n/a').reduce((total, d) => total + hundredths(d), 0n));
}

/** What a claim's late charge depends on: the sheet's today (yyyy-mm-dd), its terms in days and its late percent (two decimals). */
export type Late = { today: string; terms: number; pct: string };

/** The claim's due-by (yyyy-mm-dd): its date plus the sheet's terms in days. */
export function dueBy(claim: Claim, terms: number): string {
  const d = new Date(`${claim.date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + terms);
  return d.toISOString().slice(0, 10);
}

/** An OPEN claim whose due-by is before the sheet's today. */
export const isOverdue = (claim: Claim, terms: number, today: string) =>
  claim.status === 'OPEN' && today !== '' && dueBy(claim, terms) < today;

/** The full 30 days the claim has been overdue on the sheet's today (0 when it is not overdue). */
function lateMonths(claim: Claim, { today, terms }: Late): bigint {
  if (!isOverdue(claim, terms, today)) return 0n;
  const days = (Date.parse(`${today}T00:00:00Z`) - Date.parse(`${dueBy(claim, terms)}T00:00:00Z`)) / 86_400_000;
  return BigInt(Math.floor(days / 30));
}

/**
 * A claim's figure: a settled claim's frozen due (its late charge frozen in), otherwise the figure its
 * person's last statement bound it to, otherwise its amount times the rate, on the claim's date, of
 * the grade its person had on that date, raised to the sheet's `floor` (two decimals). An overdue claim's late charge — the late
 * percent of that figure for every full 30 days overdue, half to even — is added on top: a statement
 * never binds it, so it follows the sheet's today.
 */
export function figure(claim: Claim, rates: Rate[], person: Person | undefined, floor: string, late: Late): string {
  if (claim.settledDue !== null) return claim.settledDue;
  const bound = claim.stated ? (claim.statedDue ?? 'n/a') : floored(due(claim.amount, rateFor(rates, gradeOn(person, claim.date), claim.date)), floor);
  const months = lateMonths(claim, late);
  if (bound === 'n/a' || months === 0n) return bound;
  return show(hundredths(bound) + dueCents(show(hundredths(bound) * months), late.pct));
}

function floored(live: string, floor: string): string {
  return live === 'n/a' || hundredths(live) >= hundredths(floor) ? live : show(hundredths(floor));
}
import { useQuery } from '@tanstack/react-query';
import { ClaimCells } from '../../slots/defs/claimColumns';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { claimsQuery, counts } from '../claims/claimsQuery';
import type { Claim } from '../claims/claimsQuery';
import { peopleQuery } from '../people/peopleQuery';
import type { Person } from '../people/peopleQuery';
import { useSheetToday } from '../sheet/useSheetToday';
import { useFloor, useLate, useTerms } from '../settings/settingsQuery';
import { dueBy, figure, isOverdue, ratesQuery, sumDue } from './ratesQuery';

function useOverdueData(sheetId: string) {
  return {
    people: useQuery(peopleQuery(sheetId)).data ?? [],
    claims: useQuery(claimsQuery(sheetId)).data ?? [],
    rates: useQuery(ratesQuery(sheetId)).data ?? [],
    today: useSheetToday(sheetId),
    floor: useFloor(sheetId),
    terms: useTerms(sheetId),
    late: useLate(sheetId),
  };
}

type OverdueData = ReturnType<typeof useOverdueData>;

/** The overdue claims that count (a held person's OPEN claims do not), of one person or of the sheet, with their figures, late charges included. */
function overdue({ people, claims, rates, today, floor, terms, late }: OverdueData, person?: Person) {
  const overdueClaims = claims.filter(
    (c) => (!person || c.personId === person.id) && counts(c, people) && isOverdue(c, terms, today),
  );
  const figures = overdueClaims.map((c) => figure(c, rates, people.find((p) => p.id === c.personId), floor, late));
  return { count: overdueClaims.length, total: sumDue(figures) };
}

function ClaimDueBy({ sheetId, claim }: { sheetId: string; claim: Claim }) {
  const { today, terms } = useOverdueData(sheetId);
  return (
    <>
      <td data-testid="claim-due-by">{dueBy(claim, terms)}</td>
      <td data-testid="claim-overdue">{isOverdue(claim, terms, today) ? 'yes' : 'no'}</td>
    </>
  );
}

function PersonOverdue({ sheetId, personId }: { sheetId: string; personId: number }) {
  const data = useOverdueData(sheetId);
  const person = data.people.find((p) => p.id === personId);
  const { count, total } = person ? overdue(data, person) : { count: 0, total: '0.00' };
  return (
    <td>
      <span data-testid="person-overdue-count">{count}</span> /{' '}
      <span data-testid="person-overdue-total">{total}</span>
    </td>
  );
}

function OverdueTotal({ sheetId }: { sheetId: string }) {
  const { count, total } = overdue(useOverdueData(sheetId));
  return (
    <p data-testid="rollup-overdue">
      Overdue <strong data-testid="rollup-overdue-count">{count}</strong> totalling{' '}
      <strong data-testid="rollup-overdue-total">{total}</strong>
    </p>
  );
}

export const contributions = [
  ClaimCells.fill({ order: 12, Component: ClaimDueBy }),
  PersonHeaders.fill({ order: 16, Component: () => <th>Overdue</th> }),
  PersonCells.fill({ order: 16, Component: PersonOverdue }),
  SheetPanel.fill({ order: 26, Component: OverdueTotal }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheetQuery';
import { useSheetToday } from '../sheet/useSheetToday';
import type { Late } from '../rates/ratesQuery';

/** `clerkLimit` has two decimals ("1.50"), or is "" when there is no limit; `floor` has two decimals;
 *  `terms` is a whole number of days ("14"); `latePct` is a percent with two decimals ("0.00"). */
export type Settings = { clerkLimit: string; floor: string; terms: string; latePct: string };

/** What the request carries: a setting left out (or blank, for the floor, terms and late percent) is left as it is. */
export type SettingsChange = { clerkLimit?: string; floor?: string; terms?: string; latePct?: string };

/** The floor a sheet starts with. */
export const DEFAULT_FLOOR = '1.00';

/** The terms a sheet starts with, in days. */
export const DEFAULT_TERMS = '14';

/** The late percent a sheet starts with. */
export const DEFAULT_LATE_PCT = '0.00';

export type RoleName = 'clerk' | 'steward';

/** The role a sheet gives a user name; a name with no entry is a clerk. */
export type Role = { user: string; role: RoleName };

export const ROLES: RoleName[] = ['clerk', 'steward'];

/** Under the sheet's key, so re-loading the sheet re-reads its settings and roles. */
export const settingsKey = (sheetId: string) => [...sheetKey(sheetId), 'settings'] as const;
export const rolesKey = (sheetId: string) => [...sheetKey(sheetId), 'roles'] as const;

export const settingsQuery = (sheetId: string) => ({
  queryKey: settingsKey(sheetId),
  queryFn: () => getJson<Settings>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`),
});

/** The sheet's floor: what a claim's live due is at least. */
export function useFloor(sheetId: string): string {
  return useQuery(settingsQuery(sheetId)).data?.floor ?? DEFAULT_FLOOR;
}

/** The sheet's terms in days: how long after its date a claim is due by. */
export function useTerms(sheetId: string): number {
  return Number(useQuery(settingsQuery(sheetId)).data?.terms ?? DEFAULT_TERMS);
}

/** The sheet's late percent: what an overdue claim gains of its figure for every full 30 days it is overdue. */
export function useLatePct(sheetId: string): string {
  return useQuery(settingsQuery(sheetId)).data?.latePct ?? DEFAULT_LATE_PCT;
}

/** What a claim's late charge depends on, as the sheet has it now. */
export function useLate(sheetId: string): Late {
  return { today: useSheetToday(sheetId), terms: useTerms(sheetId), pct: useLatePct(sheetId) };
}

export const rolesQuery = (sheetId: string) => ({
  queryKey: rolesKey(sheetId),
  queryFn: () => getJson<Role[]>(`/api/sheets/${encodeURIComponent(sheetId)}/roles`),
});

